package store

import (
	"sort"
	"strings"
	"time"
)

// customerRetention is how long a deleted customer can be restored before it is purged.
const customerRetention = 30 * 24 * time.Hour

// CreateCustomer adds a customer to an organization. A customer's email address is unique within the organization,
// ignoring case.
func (s *Store) CreateCustomer(orgID, name, email string, now time.Time) (Customer, error) {
	name, email = strings.TrimSpace(name), strings.TrimSpace(email)
	if name == "" || !validEmail(email) {
		return Customer{}, invalid("a customer needs a name and a valid email address")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[orgID]; !ok {
		return Customer{}, ErrNotFound
	}
	key := emailKey(orgID, email)
	if _, ok := s.customersByEmail[key]; ok {
		return Customer{}, ErrEmailTaken
	}
	c := Customer{ID: s.newID("cus"), OrgID: orgID, Name: name, Email: email, CreatedAt: now.UTC()}
	s.customers[c.ID] = c
	s.customersByEmail[key] = c.ID
	return c, nil
}

// Customer returns one of an organization's customers that is not deleted.
func (s *Store) Customer(orgID, id string) (Customer, bool) {
	c, ok := s.CustomerIncludingDeleted(orgID, id)
	return c, ok && c.DeletedAt == nil
}

// CustomerIncludingDeleted returns one of an organization's customers, deleted or not. Invoices and payments use it: they
// stay readable after their customer is deleted.
func (s *Store) CustomerIncludingDeleted(orgID, id string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID {
		return Customer{}, false
	}
	return copyCustomer(c), true
}

// CustomerByID returns a customer of any organization (background jobs and the admin tool).
func (s *Store) CustomerByID(id string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	return copyCustomer(c), ok
}

// Customers returns an organization's customers that are not deleted, oldest first.
func (s *Store) Customers(orgID string) []Customer {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Customer{}
	for _, c := range s.customers {
		if c.OrgID == orgID && c.DeletedAt == nil {
			out = append(out, copyCustomer(c))
		}
	}
	sortCustomers(out)
	return out
}

// SearchCustomers returns an organization's customers whose name or email contains q, ignoring case, oldest first.
func (s *Store) SearchCustomers(orgID, q string) []Customer {
	q = strings.ToLower(strings.TrimSpace(q))
	out := []Customer{}
	for _, c := range s.Customers(orgID) {
		if strings.Contains(strings.ToLower(c.Name), q) || strings.Contains(strings.ToLower(c.Email), q) {
			out = append(out, c)
		}
	}
	return out
}

// FindCustomerByEmail returns the organization's customer with this email address, ignoring case. A deleted customer is
// not found.
func (s *Store) FindCustomerByEmail(orgID, email string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	id, ok := s.customersByEmail[emailKey(orgID, email)]
	if !ok {
		return Customer{}, false
	}
	return copyCustomer(s.customers[id]), true
}

// UpdateCustomer changes a customer with f, which may refuse with an error. The ID and organization cannot change, and a
// deleted customer cannot be changed.
func (s *Store) UpdateCustomer(orgID, id string, f func(*Customer) error) (Customer, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.customers[id]
	if !ok || old.OrgID != orgID || old.DeletedAt != nil {
		return Customer{}, ErrNotFound
	}
	c := copyCustomer(old)
	if err := f(&c); err != nil {
		return Customer{}, err
	}
	c.ID, c.OrgID, c.CreatedAt = old.ID, old.OrgID, old.CreatedAt
	c.Name, c.Email = strings.TrimSpace(c.Name), strings.TrimSpace(c.Email)
	if c.Name == "" || !validEmail(c.Email) {
		return Customer{}, invalid("a customer needs a name and a valid email address")
	}
	if c.DefaultPaymentMethod != "" && !strings.HasPrefix(c.DefaultPaymentMethod, "pm_") {
		return Customer{}, invalid("a payment method looks like pm_...")
	}
	if newKey := emailKey(orgID, c.Email); newKey != emailKey(orgID, old.Email) {
		if _, ok := s.customersByEmail[newKey]; ok {
			return Customer{}, ErrEmailTaken
		}
		delete(s.customersByEmail, emailKey(orgID, old.Email))
		s.customersByEmail[newKey] = c.ID
	}
	s.customers[id] = c
	return copyCustomer(c), nil
}

// DeleteCustomer erases a customer at once, without the retention of SoftDeleteCustomer. Its invoices keep no customer.
func (s *Store) DeleteCustomer(orgID, id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID {
		return ErrNotFound
	}
	delete(s.customers, id)
	if s.customersByEmail[emailKey(orgID, c.Email)] == id {
		delete(s.customersByEmail, emailKey(orgID, c.Email))
	}
	return nil
}

// SoftDeleteCustomer deletes a customer at now. It is hidden from the organization, and its email address is free again,
// until it is restored (within 30 days) or purged. A customer with a subscription that is not canceled cannot be deleted.
func (s *Store) SoftDeleteCustomer(orgID, id string, now time.Time) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt != nil {
		return ErrNotFound
	}
	for _, sub := range s.subs {
		if sub.CustomerID == id && sub.Status != Canceled {
			return ErrActiveSubscriptions
		}
	}
	t := now.UTC()
	c.DeletedAt = &t
	s.customers[id] = c
	if s.customersByEmail[emailKey(orgID, c.Email)] == id {
		delete(s.customersByEmail, emailKey(orgID, c.Email))
	}
	return nil
}

// RestoreCustomer undoes the deletion of a customer deleted no more than 30 days before now. Its email address must not be
// in use by another customer of the organization (ErrEmailTaken).
func (s *Store) RestoreCustomer(orgID, id string, now time.Time) (Customer, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt == nil || now.After(c.DeletedAt.Add(customerRetention)) {
		return Customer{}, ErrNotFound
	}
	key := emailKey(orgID, c.Email)
	if _, ok := s.customersByEmail[key]; ok {
		return Customer{}, ErrEmailTaken
	}
	c.DeletedAt = nil
	s.customers[id] = c
	s.customersByEmail[key] = id
	return copyCustomer(c), nil
}

// PurgeDeletedCustomers erases the customers deleted more than 30 days before now and returns how many it erased. Their
// invoices and payments stay, without their customer.
func (s *Store) PurgeDeletedCustomers(now time.Time) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := 0
	for id, c := range s.customers {
		if c.DeletedAt != nil && now.After(c.DeletedAt.Add(customerRetention)) {
			delete(s.customers, id)
			n++
		}
	}
	return n
}

func copyCustomer(c Customer) Customer {
	if c.Metadata != nil {
		m := make(map[string]string, len(c.Metadata))
		for k, v := range c.Metadata {
			m[k] = v
		}
		c.Metadata = m
	}
	return c
}

func sortCustomers(cs []Customer) {
	sort.Slice(cs, func(i, j int) bool {
		if !cs[i].CreatedAt.Equal(cs[j].CreatedAt) {
			return cs[i].CreatedAt.Before(cs[j].CreatedAt)
		}
		return cs[i].ID < cs[j].ID
	})
}

