func TestSoftDeleteCustomer(t *testing.T) {
	s := New()
	a, b := newOrg(t, s, "A"), newOrg(t, s, "B")
	jane, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	p, _ := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: money.USD, UnitAmount: 100, Interval: Monthly}, t0)
	inv, err := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: jane.ID, Currency: money.USD, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 100}}}, t0)
	if err != nil {
		t.Fatal(err)
	}
	sub, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: jane.ID, PlanID: p.ID, Quantity: 1, Status: Trialing, StartedAt: t0,
		CurrentPeriodStart: t0, CurrentPeriodEnd: t0.AddDate(0, 1, 0)}, t0)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.SoftDeleteCustomer(a.ID, jane.ID, t0); !errors.Is(err, ErrActiveSubscriptions) || !errors.Is(err, ErrConflict) {
		t.Fatalf("delete with a subscription that is not canceled: %v", err)
	}
	if _, err := s.UpdateSubscription(a.ID, sub.ID, func(x *Subscription) error { x.Status = Canceled; return nil }); err != nil {
		t.Fatal(err)
	}
	if err := s.SoftDeleteCustomer(b.ID, jane.ID, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("deleted through another org: %v", err)
	}

	deletedAt := t0.Add(time.Hour)
	if err := s.SoftDeleteCustomer(a.ID, jane.ID, deletedAt); err != nil {
		t.Fatal(err)
	}
	if got, ok := s.CustomerIncludingDeleted(a.ID, jane.ID); !ok || got.DeletedAt == nil || !got.DeletedAt.Equal(deletedAt) {
		t.Fatalf("CustomerIncludingDeleted = %+v, %v", got, ok)
	}
	if _, ok := s.Customer(a.ID, jane.ID); ok {
		t.Fatal("deleted customer is visible")
	}
	if got := s.Customers(a.ID); len(got) != 0 {
		t.Fatalf("Customers = %+v", got)
	}
	if got := s.SearchCustomers(a.ID, "jane"); len(got) != 0 {
		t.Fatalf("SearchCustomers = %+v", got)
	}
	if _, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); ok {
		t.Fatal("deleted customer found by email")
	}
	if err := s.SoftDeleteCustomer(a.ID, jane.ID, deletedAt); !errors.Is(err, ErrNotFound) {
		t.Fatalf("deleted twice: %v", err)
	}
	if _, err := s.UpdateCustomer(a.ID, jane.ID, func(c *Customer) error { c.Name = "Jane 2"; return nil }); !errors.Is(err, ErrNotFound) {
		t.Fatalf("update a deleted customer: %v", err)
	}
	if _, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: jane.ID, PlanID: p.ID, Quantity: 1, Status: Active, StartedAt: t0,
		CurrentPeriodStart: t0, CurrentPeriodEnd: t0.AddDate(0, 1, 0)}, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("subscription for a deleted customer: %v", err)
	}
	if _, err := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: jane.ID, Currency: money.USD, Lines: []Line{{Description: "y", Quantity: 1, UnitAmount: 1}}}, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("invoice for a deleted customer: %v", err)
	}
	if got, ok := s.Invoice(a.ID, inv.ID); !ok || got.CustomerID != jane.ID {
		t.Fatalf("invoice of a deleted customer = %+v, %v", got, ok)
	}

	// Its email address is free again.
	again, err := s.CreateCustomer(a.ID, "Jane Again", "JANE@example.com", deletedAt)
	if err != nil {
		t.Fatalf("email of a deleted customer: %v", err)
	}
	// Restoring is refused while another customer uses the address, and allowed once it is free.
	if _, err := s.RestoreCustomer(a.ID, jane.ID, deletedAt); !errors.Is(err, ErrEmailTaken) {
		t.Fatalf("restore with the email taken: %v", err)
	}
	if _, err := s.UpdateCustomer(a.ID, again.ID, func(c *Customer) error { c.Email = "jane2@example.com"; return nil }); err != nil {
		t.Fatal(err)
	}
	if _, err := s.RestoreCustomer(b.ID, jane.ID, deletedAt); !errors.Is(err, ErrNotFound) {
		t.Fatalf("restored through another org: %v", err)
	}
	restored, err := s.RestoreCustomer(a.ID, jane.ID, deletedAt.Add(time.Hour))
	if err != nil || restored.DeletedAt != nil || restored.Email != "jane@example.com" {
