	if _, err := s.RestoreCustomer(a.ID, jane.ID, deletedAt); !errors.Is(err, ErrEmailTaken) {
		t.Fatalf("restore with the email taken: %v", err)
	}
	if _, err := s.UpdateCustomer(a.ID, again.ID, func(c *Customer) error { c.Email = "jane2@example.com"; return nil }); err != nil {
		t.Fatal(err)
	}
	if _, err := s.RestoreCustomer(b.ID, jane.ID, deletedAt); !errors.Is(err, ErrNotFound) {
		t.Fatalf("restored through another org: %v", err)
	}
	restored, err := s.RestoreCustomer(a.ID, jane.ID, deletedAt.Add(time.Hour))
	if err != nil || restored.DeletedAt != nil || restored.Email != "jane@example.com" {
		t.Fatalf("RestoreCustomer = %+v, %v", restored, err)
	}
	if got, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); !ok || got.ID != jane.ID {
		t.Fatalf("restored customer not found by email: %+v %v", got, ok)
	}
	if _, err := s.RestoreCustomer(a.ID, jane.ID, deletedAt.Add(time.Hour)); !errors.Is(err, ErrNotFound) {
		t.Fatalf("restore a customer that is not deleted: %v", err)
	}

	// A snapshot keeps a deleted customer's email free too.
	if err := s.SoftDeleteCustomer(a.ID, jane.ID, deletedAt.Add(2*time.Hour)); err != nil {
		t.Fatal(err)
	}
	s2, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if _, ok := s2.FindCustomerByEmail(a.ID, "jane@example.com"); ok {
		t.Fatal("a snapshot indexes a deleted customer's email")
	}
	if _, err := s2.CreateCustomer(a.ID, "Jane 3", "jane@example.com", t0); err != nil {
		t.Fatalf("email after a snapshot: %v", err)
	}
}

