func TestPurgeDeletedCustomers(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	old, _ := s.CreateCustomer(a.ID, "Old", "old@example.com", t0)
	recent, _ := s.CreateCustomer(a.ID, "Recent", "recent@example.com", t0)
	live, _ := s.CreateCustomer(a.ID, "Live", "live@example.com", t0)
	inv, _ := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: old.ID, Currency: money.USD, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 100}}}, t0)
	if err := s.SoftDeleteCustomer(a.ID, old.ID, t0); err != nil {
		t.Fatal(err)
	}
	if err := s.SoftDeleteCustomer(a.ID, recent.ID, t0.AddDate(0, 0, 20)); err != nil {
		t.Fatal(err)
	}

	now := t0.AddDate(0, 0, 31)
	if n := s.PurgeDeletedCustomers(now); n != 1 {
		t.Fatalf("PurgeDeletedCustomers = %d, want 1", n)
	}
	if _, ok := s.CustomerIncludingDeleted(a.ID, old.ID); ok {
		t.Fatal("purged customer is still there")
	}
	if got, ok := s.CustomerIncludingDeleted(a.ID, recent.ID); !ok || got.DeletedAt == nil {
		t.Fatalf("recently deleted customer was purged: %+v, %v", got, ok)
	}
	if _, ok := s.Customer(a.ID, live.ID); !ok {
		t.Fatal("live customer was purged")
	}
	if got, ok := s.Invoice(a.ID, inv.ID); !ok || got.CustomerID != old.ID {
		t.Fatalf("invoice of a purged customer = %+v, %v", got, ok)
	}
	if n := s.PurgeDeletedCustomers(now); n != 0 {
		t.Fatalf("second PurgeDeletedCustomers = %d, want 0", n)
	}
}

