		t.Fatalf("invoice customer after restore = %+v", inv.Customer)
	}
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore a customer that is not deleted: %s", r)
	}
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Globex.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore through another org: %s", r)
	}

	// After 30 days a deleted customer cannot be restored.
	kim := e.CreateCustomer(e.Acme, "Kim", "kim@example.com")
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+kim.ID, e.Acme.Key, nil, nil)
	e.Clock.Advance(31 * 24 * time.Hour)
	if r := e.Do("POST", "/v1/customers/"+kim.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("restore after 30 days: %s", r)
	}
	if r := e.Do("POST", "/v1/customers/"+kim.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore after 30 days, again: %s", r)
	}
}

