func TestDeleteCustomer(t *testing.T) {
	e := apitest.New(t)
	jane := e.CreateCustomer(e.Acme, "Jane Doe", "jane@example.com")
	john := e.CreateCustomer(e.Acme, "John Roe", "john@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")

	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": jane.ID, "plan_id": p.ID, "quantity": 1}, &sub)
	if r := e.Do("DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "has_active_subscriptions" {
		t.Fatalf("delete with an active subscription: %s", r)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+sub.ID+"/cancel", e.Acme.Key, nil, nil)

	var inv struct {
		ID       string `json:"id"`
		Customer *struct {
			ID, Name, Email string
			Deleted         bool
		} `json:"customer"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": jane.ID, "currency": "USD",
		"lines": []map[string]any{{"description": "Setup", "quantity": 1, "unit_amount": 1000}}}, &inv)
	var paid struct {
		Payment store.Payment `json:"payment"`
	}
	e.MustDo(http.StatusOK, "POST", "/v1/invoices/"+inv.ID+"/pay", e.Acme.Key, map[string]string{"payment_method": "pm_card_visa"}, &paid)

	e.Clock.Advance(time.Hour)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil, nil)
	if n := len(e.Store.Events(e.Acme.ID, "customer.deleted")); n != 1 {
		t.Fatalf("customer.deleted events = %d, want 1", n)
	}

	for _, c := range []struct {
		method, path string
		body         any
	}{
		{"GET", "/v1/customers/" + jane.ID, nil},
		{"PATCH", "/v1/customers/" + jane.ID, map[string]any{"name": "Jane 2"}},
		{"DELETE", "/v1/customers/" + jane.ID, nil},
		{"POST", "/v1/invoices", map[string]any{"customer_id": jane.ID, "currency": "USD", "lines": []map[string]any{{"description": "x", "quantity": 1, "unit_amount": 1}}}},
		{"POST", "/v1/subscriptions", map[string]any{"customer_id": jane.ID, "plan_id": p.ID, "quantity": 1}},
	} {
		if r := e.Do(c.method, c.path, e.Acme.Key, c.body); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
			t.Fatalf("%s %s on a deleted customer: %s", c.method, c.path, r)
		}
	}

	var page struct {
		Items []store.Customer `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/customers", e.Acme.Key, nil, &page)
	if len(page.Items) != 1 || page.Items[0].ID != john.ID {
		t.Fatalf("list = %+v", page.Items)
	}
	for _, q := range []string{"q=jane", "email=jane@example.com"} {
		page.Items = nil
		e.MustDo(http.StatusOK, "GET", "/v1/customers?"+q, e.Acme.Key, nil, &page)
		if len(page.Items) != 0 {
			t.Fatalf("%s = %+v", q, page.Items)
		}
	}
	if r := e.MustDo(http.StatusOK, "GET", "/v1/customers/export.csv", e.Acme.Key, nil, nil); strings.Contains(string(r.Body), jane.ID) {
		t.Fatalf("export includes a deleted customer: %s", r.Body)
	}

	// Its invoices and payments stay readable, with the customer marked deleted.
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &inv)
	if inv.Customer == nil || inv.Customer.Name != "Jane Doe" || !inv.Customer.Deleted {
		t.Fatalf("invoice customer = %+v", inv.Customer)
	}
	var payments struct {
		Items []store.Payment `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/payments?invoice_id="+inv.ID, e.Acme.Key, nil, &payments)
	if len(payments.Items) != 1 || payments.Items[0].ID != paid.Payment.ID {
		t.Fatalf("payments = %+v", payments.Items)
	}

	// Its email address is free again, but while another customer uses it, it cannot be restored.
	again := e.CreateCustomer(e.Acme, "Jane Again", "JANE@example.com")
	e.Clock.Advance(10 * 24 * time.Hour)
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "email_taken" {
		t.Fatalf("restore with the email taken: %s", r)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+again.ID, e.Acme.Key, map[string]any{"email": "jane2@example.com"}, nil)
	var restored store.Customer
	e.MustDo(http.StatusOK, "POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil, &restored)
	if restored.ID != jane.ID || restored.DeletedAt != nil {
		t.Fatalf("restored = %+v", restored)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/customers/"+jane.ID, e.Acme.Key, nil, &restored)
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &inv)
	if inv.Customer == nil || inv.Customer.Deleted {
		t.Fatalf("invoice customer after restore = %+v", inv.Customer)
	}
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore a customer that is not deleted: %s", r)
	}
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Globex.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore through another org: %s", r)
	}

	// After 30 days a deleted customer cannot be restored.
	kim := e.CreateCustomer(e.Acme, "Kim", "kim@example.com")
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+kim.ID, e.Acme.Key, nil, nil)
	e.Clock.Advance(31 * 24 * time.Hour)
	if r := e.Do("POST", "/v1/customers/"+kim.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("restore after 30 days: %s", r)
	}
	if r := e.Do("POST", "/v1/customers/"+kim.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore after 30 days, again: %s", r)
	}
}

